import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(-1.25, -1.1, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load GLB mesh
  const gearScene = ctx.glbLoader('/prism-mock/orrery/meshes/gear-a.glb').scene.clone();
  const mesh = gearScene.children[0]; // assume single mesh

  // Optional: ensure material properties for machined-metal look
  if (mesh.isMesh && mesh.material) {
    const mat = mesh.material;
    // Set PBR properties per design tokens (if not already present)
    mat.metalness = 0.55;
    mat.roughness = 0.5;
    mat.clearcoat = 0.25;
    // Brushed anisotropy - requires anisotropy property, not standard in MeshStandardMaterial
    // We'll skip or use MeshPhysicalNodeMaterial? Since GLB likely has it.
    // For WebGPU, use node material if needed:
    // if (mat.isMeshStandardMaterial) {
    //   mat.anisotropy = 0.5;
    //   mat.anisotropyRotation = Math.PI / 4;
    // }
  }
  group.add(mesh);

  // Weighted-settle entrance animation
  const tl = gsap.timeline({ paused: true });
  tl.fromTo(group.scale, { x: 0, y: 0, z: 0 }, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.4,
    ease: 'power4.out',
    onComplete: () => {
      gsap.to(group.scale, {
        x: 1, y: 1, z: 1,
        duration: 0.3,
        ease: 'power4.out'
      });
    }
  });
  tl.play();

  // Interactions
  let hoverTween = null;
  group.userData.handlers = {
    pointerenter: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: group.position.y + 0.15,
        duration: 0.3,
        ease: 'power2.out'
      });
    },
    pointerleave: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: group.position.y,
        duration: 0.3,
        ease: 'power2.out'
      });
    },
    click: () => {
      // Emit hub-features.select event (assumes context can handle)
      if (config.onAction) {
        config.onAction('hub-features.select');
      }
      // Also fire a custom event on the group for broader compatibility
      group.dispatchEvent({ type: 'select', source: 'hub-features' });
    }
  };

  // Cinematic primitives
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach(primitive => {
      const fn = ctx.primitives[primitive.name];
      if (fn) {
        fn(group, primitive.params);
      }
    });
  }

  // Cleanup
  group.userData.cleanup = () => {
    tl.kill();
    if (hoverTween) hoverTween.kill();
    // Dispose mesh geometry and material if cloned
    mesh.geometry.dispose();
    if (mesh.material) {
      if (Array.isArray(mesh.material)) {
        mesh.material.forEach(m => m.dispose());
      } else {
        mesh.material.dispose();
      }
    }
    // Remove from parent if added to scene
    if (group.parent) {
      group.parent.remove(group);
    }
  };

  return group;
}
